using System.Linq;using ROM.Horde;using ROM.Progression;
namespace ROM.UI.Sprint01 {public sealed partial class RiftVillageUI {
 void JournalChanged(){if(CinematicDialogue&&!string.IsNullOrEmpty(dialogueQuest))ShowQuests(TalkingTo);}
 public void ShowQuests(RiftVillageNpc npc){if(!dialog||TalkingTo!=npc)return;var catalog=RiftJournalCatalog.Load;if(!catalog)return;var state=RiftJournalView.Read();var definitions=catalog.Quests.Where(q=>q&&(q.Giver==npc.Id&&state.Available(q)||q.TurnIn==npc.Id&&state.Quest(q.Id)!=null&&!state.TurnedIn(q.Id))).ToArray();if(definitions.Length==0){ShowDialogueGreeting(npc);speech.text=ROM.Tutorial.Crilium.CriliumSession.Active&&!ROM.Tutorial.Crilium.CriliumSession.CanOfferQuest(ROM.Tutorial.Crilium.CriliumDefinition.Load.QuestId)?"Primero probá el movimiento y la cámara indicados arriba. Después te doy la misión de entrenamiento.":"No tengo nuevas misiones para vos por ahora.";return;}int index=System.Array.FindIndex(definitions,q=>q.Id==dialogueQuest);ShowDialogueQuest(npc,definitions,index<0?0:index);}
}}
